const choose=document.querySelector('#date-choice');choose?.addEventListener('change',()=>location.assign(choose.value));const mark=document.querySelector('[data-revision]');function clock(){document.querySelectorAll('[data-kickoff]').forEach(e=>{if(e.dataset.final==='true')return;e.textContent=Date.now()<Date.parse(e.dataset.kickoff)?'尚未到计划开球时间':'已到计划开球时间，赛况待核验';});}clock();setInterval(clock,60000);const root=new URL('.',document.currentScript.src);async function check(){try{const r=await fetch(new URL('site-manifest.json?t='+Date.now(),root),{cache:'no-store'});if(!r.ok)return;const m=await r.json();if(mark?.dataset.latest==='true'&&m.revision!==mark.dataset.revision){const u=new URL('index.html',root);u.searchParams.set('v',m.revision);location.replace(u);}}catch{}}setInterval(check,60000);